"""Offline typography and layout for data-derived engineering diagrams."""

CSS = """
:root{--ink:#243e62;--muted:#667f9f;--blue:#2d6cdf;--line:#d8e4f3;--navy:#142b4b}
*{box-sizing:border-box}html{scroll-behavior:auto}body{margin:0;background:#eff4fb;color:var(--ink);font:14px/1.8 "Microsoft YaHei UI","Microsoft YaHei","Segoe UI",sans-serif}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}a:focus-visible,summary:focus-visible{outline:2px solid #2d6cdf;outline-offset:5px}p,h1,h2,h3,h4,dl{margin:0}code{font:12px/1.7 Consolas,"Cascadia Code",monospace;overflow-wrap:anywhere}
#figure{position:absolute;top:0;left:0}.masthead{background:var(--navy);color:#d2e1f5}.masthead>div{max-width:1320px;min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:20px;margin:auto;padding:0 10px}.brand{display:flex;align-items:center;gap:12px;color:white}.brand:hover{text-decoration:none}.brand svg{width:37px;height:37px;padding:6px;border:1px solid #5c84be;border-radius:10px;background:#255fbd;fill:none;stroke:white;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.brand strong{font-size:23px;letter-spacing:1px}.brand>span{margin-left:5px;color:#9cb7d9;font:12px "Segoe UI",sans-serif}.masthead-label{color:#a2bddf;font-size:12px}
main{max-width:1320px;margin:0 auto;padding:30px 10px 24px}.page-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:21px}h1{font-size:30px;line-height:1.5;font-weight:650;letter-spacing:-.5px}.page-heading p{margin-top:6px;color:var(--muted);font-size:13px}.capture-link,.capture-back{font-size:12px;flex-shrink:0}.capture-back{display:none}.scope{display:flex;align-items:center;gap:10px;margin-bottom:22px;padding:11px 16px;border:1px solid #d3e2f5;border-radius:8px;background:#f7faff;font-size:12px;color:#617b9e}.scope strong{font-weight:600;color:#426796}.scope-symbol{display:grid;place-items:center;flex-shrink:0;width:19px;height:19px;border:1px solid #88a6ce;border-radius:50%;font:600 12px "Segoe UI",sans-serif}
.scenario{background:white;border:1px solid var(--line);border-radius:13px;overflow:hidden}.featured{padding:25px 28px 0}.case-heading{display:flex;align-items:center;justify-content:space-between;gap:20px}.case-source{display:block;margin-bottom:8px;color:#6986aa;font-size:12px}h2{color:#294c79;font-size:21px;line-height:1.65;font-weight:600}.case-state{padding:5px 12px;border:1px solid #eadbbd;border-radius:6px;color:#8a642d;background:#fff8ec;font-size:12px;white-space:nowrap}.why{max-width:78em;margin-top:13px;color:#657f9f;line-height:1.9;font-size:13px}.cue-line{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:17px 0 20px;color:#7b91ad;font-size:11px}.cue-line>b{display:inline-block;padding:2px 8px;border:1px solid #d6e5f8;border-radius:4px;color:#4a74ac;background:#f7faff;font:600 12px/1.8 "Segoe UI",sans-serif}.cue-line>span:last-child{margin-left:auto;color:#8b9db6}
.graph-scroll{overflow-x:auto;border:1px solid #e0e9f5;border-radius:10px;background-color:#f6f9fe;background-image:radial-gradient(#cad9ed .75px,transparent .75px);background-size:18px 18px}.graph{display:block;width:100%;min-width:650px;height:auto;max-height:640px}.graph text{font-family:"Microsoft YaHei UI","Microsoft YaHei",sans-serif}.graph .node-title{font-size:28px;font-weight:600;fill:#2b4d78}.graph .node-kind{font:14px Consolas,"Cascadia Code",monospace;fill:#5a7496}.graph .node-premise{font-size:19px;fill:#4f6f98}.graph .node-origin{font-size:15px;fill:#5a7496}.graph .edge-label{font-size:17px;fill:#567ba8;paint-order:stroke;stroke:#f6f9fe;stroke-width:8px;stroke-linejoin:round}
.graph-key{display:flex;align-items:center;justify-content:flex-end;gap:19px;flex-wrap:wrap;padding:13px 1px 17px;font-size:11px;color:#7e91ab}.graph-key>span:first-child{margin-right:auto}.label{font-weight:600}.label.IN{color:#23775d}.label.OUT{color:#b34d45}.label.UNDECIDED{color:#916321}.label i{display:inline-block;width:6px;height:6px;margin-right:6px;border-radius:50%;background:currentColor;vertical-align:middle}
.decision{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:19px 20px;border:1px solid #dce6f5;border-radius:9px;background:#f0f6ff}.decision>div{display:flex;align-items:center;flex-wrap:wrap;gap:13px}.decision>div>span{color:#7189a9;font-size:12px}.decision strong{color:#315c98;font-size:20px;font-weight:600}.decision code{padding:4px 9px;border:1px solid #d5e4f8;border-radius:5px;color:#547bae;background:#fff;font-size:11px}.decision dl{display:flex;gap:30px}.decision dt{color:#8195b0;font-size:10px;margin-bottom:4px}.decision dd{margin:0;color:#5d7da7;font:11px/1.8 Consolas,"Cascadia Code",monospace}
.raw-record{margin-top:17px;border-top:1px solid #e5edf7}.raw-record>summary{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:15px 0;color:#5e7da6;font-size:12px;cursor:pointer;list-style:none}.raw-record>summary:after{content:"＋";font-size:16px;color:#90a6c1}.raw-record[open]>summary:after{content:"－"}.raw-record>summary>span{margin-left:auto;font-size:11px;color:#7f94ae}.raw-record h4{margin:18px 0 10px;color:#6b85a6;font-size:12px}.raw-record>p{padding-bottom:20px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:10px;border-bottom:1px solid #e3ebf6;text-align:left;vertical-align:top}th{background:#f5f8fd;color:#7590b0;font-size:11px;font-weight:500}td code{font-size:10px}.attacks{display:grid;gap:8px;padding:0 0 0 15px;font-size:11px}.attacks li{overflow-wrap:anywhere}.attacks span{margin:0 9px;color:#8ba0bb}.attacks code{font-size:10px}
.provenance{display:grid;grid-template-columns:1fr .8fr 1.4fr;gap:0;margin-top:19px;padding:17px 5px;color:#6d85a5}.provenance>div{display:flex;flex-direction:column;gap:5px;padding:0 22px;border-left:1px solid #d5e2f3}.provenance>div:first-child{padding-left:0;border-left:0}.provenance span{font-size:10px;color:#7e93af}.provenance b{font-size:12px;font-weight:500;color:#4e719e}.provenance small{font-size:10px;color:#8298b5}.other-scenarios{margin-top:42px;border-top:1px solid var(--line);padding-top:26px}.other-scenarios>h2{font-size:18px}.muted{font-size:12px;color:#7a90ac}.other-scenarios>.muted{margin:8px 0 20px}.secondary-case{margin-bottom:14px}.secondary-case>summary{display:flex;justify-content:space-between;gap:16px;align-items:center;list-style:none;cursor:pointer;padding:19px 23px;font-size:14px;color:#4b709d}.secondary-case>summary>span{font-size:11px;color:#8a9db7}.secondary-case>div{padding:24px;border-top:1px solid #e3ebf6}.secondary-case h2{font-size:18px}.secondary-case .graph{max-height:600px}.check-ok{padding:12px 0;color:#23775d;font-size:12px}.check-failed{color:#b34d45}
footer{margin-top:14px;padding:17px 0 4px;border-top:1px solid var(--line);color:#8296b1;font-size:10px}footer>span{display:flex;gap:8px;flex-wrap:wrap;align-items:center}footer small{margin-left:auto;color:#8b9eb8;font:9px Consolas,monospace;overflow-wrap:anywhere}footer>p{margin-top:7px;line-height:1.8}footer code{font-size:10px}
body:has(#figure:target) .other-scenarios,body:has(#figure:target) .capture-link,body:has(#figure:target) .raw-record{display:none}body:has(#figure:target) .capture-back{display:block}body:has(#figure:target) .featured{padding-bottom:24px}
@media(max-width:900px){main{padding:24px 18px}.masthead>div{padding:0 18px}.featured{padding:20px 20px 0}.decision{align-items:flex-start;flex-direction:column}.decision dl{gap:22px}.provenance{grid-template-columns:1fr 1fr;gap:17px}.provenance>div:last-child{grid-column:1/-1;border-left:0;padding-left:0}h1{font-size:26px}h2{font-size:19px}footer small{margin-left:0}}
@media(max-width:600px){main{padding:20px 13px}.masthead>div{min-height:65px;padding:0 16px}.masthead-label{display:none}.page-heading{align-items:flex-start;flex-direction:column;gap:10px}h1{font-size:24px}.scope{align-items:flex-start;font-size:11px;padding:12px}.scope-symbol{margin-top:2px}.featured{padding:17px 15px 0}.case-heading{align-items:flex-start;flex-direction:column;gap:10px}.case-heading h2{font-size:18px}.case-source{font-size:10px}.cue-line{gap:7px}.cue-line>span:last-child{width:100%;margin-left:0}.why{font-size:12px}.graph-key{gap:12px;justify-content:flex-start}.graph-key>span:first-child{width:100%}.decision{padding:15px}.decision>div{gap:9px}.decision dl{flex-wrap:wrap;gap:13px}.decision strong{font-size:19px}.decision dd{overflow-wrap:anywhere;font-size:10px}.raw-record>summary{flex-wrap:wrap;font-size:11px}.raw-record>summary>span{margin-left:0}.provenance{grid-template-columns:1fr;gap:16px}.provenance>div{padding-left:0;border-left:0}.provenance>div:last-child{grid-column:auto}.secondary-case>summary{align-items:flex-start;flex-direction:column;gap:5px;padding:17px}.secondary-case>div{padding:16px}.brand strong{font-size:21px}.brand>span{font-size:10px}body:has(#figure:target) .featured{padding-bottom:17px}}
@media print{body{background:white}.masthead{background:white;color:var(--ink)}.masthead .brand,.masthead-label{color:var(--ink)}.brand>span{color:var(--muted)}main{max-width:none;padding:15px 0}.capture-link,.capture-back{display:none}.scenario{break-inside:avoid}.graph-scroll{background:#f6f9fe}.graph{min-width:0}.scope,.decision,.graph{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
"""
